const menu = document.querySelector('.menu-toggle');
const nav = document.querySelector('#navigation');
function closeMenu(){ menu.setAttribute('aria-expanded','false'); nav.classList.remove('is-open'); }
menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')==='true';menu.setAttribute('aria-expanded',String(!open));nav.classList.toggle('is-open',!open);});
nav.querySelectorAll('a').forEach(link=>link.addEventListener('click',closeMenu));
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&menu.getAttribute('aria-expanded')==='true'){closeMenu();menu.focus();}});
const form=document.querySelector('#academy-search'),city=document.querySelector('#city'),state=document.querySelector('#state'),cards=[...document.querySelectorAll('.branch')],resultCount=document.querySelector('#result-count'),empty=document.querySelector('#empty-results'),reset=document.querySelector('#reset-search');
function normalize(text){return text.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();}
function filterAcademies(){const query=normalize(city.value);let count=0;cards.forEach(card=>{const match=(!state.value||state.value===card.dataset.state)&&(!query||normalize(card.dataset.search).includes(query));card.hidden=!match;if(match)count++;});resultCount.textContent=count===1?'1 academia encontrada':`${count} academias encontradas`;empty.hidden=count!==0;reset.hidden=!city.value&&!state.value;}
form.addEventListener('submit',event=>{event.preventDefault();filterAcademies();});
city.addEventListener('input',filterAcademies);state.addEventListener('change',filterAcademies);
function clearFilters(){city.value='';state.value='';filterAcademies();city.focus();}
reset.addEventListener('click',clearFilters);document.querySelector('#show-all').addEventListener('click',clearFilters);
const journeys={beginner:{label:'PRIMEIROS PASSOS',title:'TODO FAIXA-PRETA<br>JÁ FOI INICIANTE.',copy:'Você não precisa chegar sabendo. Conheça o tatame, entenda os fundamentos e construa confiança a cada treino.',points:[['Aprenda a base','Posições, movimentos e os princípios do jiu-jitsu.'],['Evolua no seu tempo','Consistência vale mais do que pressa.'],['Treine acompanhado','Professor e parceiros fazem parte do caminho.']]},practice:{label:'EVOLUÇÃO CONTÍNUA',title:'SEMPRE HÁ UM<br>PRÓXIMO MOVIMENTO.',copy:'Aprofunde a técnica, encontre novos desafios e continue construindo seu jogo. Cada treino é uma oportunidade de evoluir.',points:[['Aprofunde a técnica','Entenda as conexões entre posições e transições.'],['Construa seu jogo','Desenvolva estratégias que combinam com você.'],['Mantenha a constância','Um caminho construído treino após treino.']]},compete:{label:'NOVOS DESAFIOS',title:'PREPARAÇÃO ANTES.<br>PRESENÇA NA LUTA.',copy:'Quer levar seu jiu-jitsu para a competição? Converse com o professor sobre seus objetivos e prepare o próximo passo com orientação.',points:[['Defina seu objetivo','Escolha seus desafios junto com o professor.'],['Refine a estratégia','Técnica, decisões e preparação para a luta.'],['Evolua com a equipe','Aprenda com o processo e com seus parceiros.']]}};
const tabs=[...document.querySelectorAll('[role="tab"]')],panel=document.querySelector('#training-panel');
function selectJourney(tab,focus=false){const data=journeys[tab.dataset.level];tabs.forEach(item=>{item.setAttribute('aria-selected',String(item===tab));item.tabIndex=item===tab?0:-1;});panel.setAttribute('aria-labelledby',tab.id);document.querySelector('#training-label').textContent=data.label;document.querySelector('#training-subtitle').innerHTML=data.title;document.querySelector('#training-copy').textContent=data.copy;document.querySelector('#training-points').replaceChildren(...data.points.map(([title,copy],index)=>{const li=document.createElement('li'),number=document.createElement('span'),content=document.createElement('div'),heading=document.createElement('h4'),text=document.createElement('p');number.textContent=String(index+1).padStart(2,'0');heading.textContent=title;text.textContent=copy;content.append(heading,text);li.append(number,content);return li;}));if(focus)tab.focus();}
tabs.forEach((tab,index)=>{tab.addEventListener('click',()=>selectJourney(tab));tab.addEventListener('keydown',event=>{let target;if(event.key==='ArrowRight'||event.key==='ArrowDown')target=(index+1)%tabs.length;if(event.key==='ArrowLeft'||event.key==='ArrowUp')target=(index-1+tabs.length)%tabs.length;if(event.key==='Home')target=0;if(event.key==='End')target=tabs.length-1;if(target!==undefined){event.preventDefault();selectJourney(tabs[target],true);}});});
// Optional structured search access in browsers that support WebMCP.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'filter_checkmat_academies',title:'Buscar academias Checkmat',description:'Filtra as matrizes visíveis por cidade, bairro ou nome e estado. Não agenda aulas nem envia mensagens.',inputSchema:{type:'object',properties:{query:{type:'string',maxLength:200},state:{type:'string',enum:['','PR','RJ']}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Array.isArray(input)||Object.keys(input).some(key=>!['query','state'].includes(key))||(input.query!==undefined&&(typeof input.query!=='string'||input.query.length>200))||(input.state!==undefined&&!['','PR','RJ'].includes(input.state)))throw new Error('Filtros inválidos.');city.value=input.query??'';state.value=input.state??'';filterAcademies();return{count:cards.filter(card=>!card.hidden).length,academies:cards.filter(card=>!card.hidden).map(card=>({name:card.querySelector('h3').textContent,state:card.dataset.state}))};}},{signal:lifecycle.signal})).catch(()=>{});}catch{}}